                    <span className="pp-turn-who">{persona.name}</span>
                    <span className="pp-turn-t">{t('transcript.liveTag')}</span>
                  </div>
                  <div className="pp-turn-text"><span className="pp-cursor" /></div>
                </div>
            }
            </div>
          </ScrollArea>
        </aside>
      }
    </div>);

}

// One transcript turn — shared by the desktop drawer and the mobile sheet.
function TranscriptTurn({ who, text, persona, at }) {
