input.content:
// app.jsx — Desktop + Mobile app shells. Each owns its own call state and its
// own session routing (transport + language, via useSessionRouting).
// The session language is also the UI locale: each shell provides `t` through
// I18nContext and stamps lang / data-lang on its root, so copy, typography and
// line-breaking all follow the one EN / 日本語 switch.
// Exports to window: DesktopApp, MobileApp.

const { useState, useEffect, useRef, useMemo } = React;

// ── Top bar (clock ticks live so the screen never feels frozen) ─────────────

function TopBar({ compact, callState }) {
  const t = useT();
  const [now, setNow] = useState(new Date());
  useEffect(() => {
    const timer = setInterval(() => setNow(new Date()), 1000);
    return () => clearInterval(timer);
  }, []);
  const hh = String(now.getHours()).padStart(2, '0');
  const mm = String(now.getMinutes()).padStart(2, '0');
  const ss = String(now.getSeconds()).padStart(2, '0');

  const live = !(callState === 'idle' || callState === 'ended');
  const sessionLabel = t(live ? 'status.live' : callState === 'ended' ? 'status.ended' : 'status.idle');
  const micLabel = t(live ? 'status.on' : 'status.off');

  return (
    <header className="pp-topbar">
      <div className="pp-brand">
        <span className="pp-brand-mark" />
        <span className="pp-brand-name">TSUBAKI</span>
        {!compact && <span className="pp-brand-sub">v0.4.2 · {t('brand.sub')}</span>}
      </div>
      <div className="pp-topbar-status">
        <span>{t('top.session')} <b style={{ color: 'var(--ink)' }}>{sessionLabel}</b></span>
        {!compact && <span>{t('top.network')} <b style={{ color: 'var(--ink)' }}>{t('status.ok')}</b></span>}
        {!compact && <span>{t('top.mic')} <b style={{ color: 'var(--ink)' }}>{micLabel}</b></span>}
        <span style={{ fontVariantNumeric: 'tabular-nums' }}>{hh}:{mm}:{ss}</span>
      </div>
    </header>);

}

// ── Sidebar ─────────────────────────────────────────────────────────────────

const NAV = [
{ id: 'call', key: 'C' },
{ id: 'personas', key: 'P' },
{ id: 'providers', key: 'V' },
{ id: 'settings', key: 'S' }];


function Sidebar({ nav, setNav, persona, provider, lang }) {
  const t = useT();
  return (
    <nav className="pp-side">
      <div className="pp-side-eyebrow">{t('side.sections')}</div>
      {NAV.map((item) =>
      <button
        key={item.id}
        className={`pp-nav-item ${nav === item.id ? 'on' : ''}`}
        onClick={() => setNav(item.id)}>
          <span>{t(`nav.${item.id}`)}</span>
          <span className="pp-nav-key">{item.key}</span>
        </button>
      )}
      <div className="pp-side-foot">
        <div><b>{persona.name}</b> · {t(`lang.name.${lang}`)}<br />{t('side.activePersona')}</div>
        <div><b>{provider.name}</b> · {provider.model}<br />{t('side.activeTransport')}</div>
        <div>{t('side.exec')} <b>{formatExec(t, provider.exec)}</b></div>
      </div>
    </nav>);

}

// Root wrapper shared by both shells: provides `t` for the session language and
// stamps lang / data-lang so i18n.css and the browser (CJK line-breaking, font
// fallback, screen-reader voice) follow it. `lang` sits on the artboard root,
// not <html>, because the canvas shows two independent sessions side by side;
// the app, with one session per document, sets document.documentElement.lang.
function LangRoot({ lang, className, accent, children }) {
  const t = useMemo(() => makeT(lang), [lang]);
  return (
    <I18nContext.Provider value={t}>
      <div className={className} lang={lang} data-lang={lang} style={{ '--accent': accent }}>
        {children}
      </div>
    </I18nContext.Provider>);
}

// ── Desktop App ─────────────────────────────────────────────────────────────

function DesktopApp({ tweaks }) {
  const [nav, setNav] = useState('call');
  const [callState, setCallState] = useState('listening'); // start in an interesting state
  const { lang, provider, persona, setPersona, changeLang, changeProvider, notice } =
  useSessionRouting({ callState, setCallState });
  const [tools, setTools] = useState(TOOLS_DEFAULT);
  // Lifted from CallView so the MicSelector in SettingsView shares the same state
  // (matches the codebase's AppShell, which threads session.muted / toggleMute
  // through to both views).
  const [muted, setMuted] = useState(false);

  // pretend the agent shifts from speaking to listening after 5s on first load
  useEffect(() => {
    if (callState !== 'listening') return;
    const timer = setTimeout(() => setCallState('speaking'), 5000);
    return () => clearTimeout(timer);
  }, []);

  return (
    <LangRoot lang={lang} className={`pp-app ${tweaks.dark ? 'pp-dark' : ''}`} accent={tweaks.accent}>
      <TopBar callState={callState} />
      <div className="pp-shell">
        <Sidebar nav={nav} setNav={setNav} persona={persona} provider={provider} lang={lang} />
        <main className="pp-main">
          <RoutingNotice notice={notice} />
          {nav === 'call' &&
          <CallView
            tweaks={tweaks}
            callState={callState}
            setCallState={setCallState}
            persona={persona}
            provider={provider}
            lang={lang}
            setLang={changeLang}
            tools={tools}
            setTools={setTools}
            muted={muted}
            setMuted={setMuted}
            dark={tweaks.dark} />
          }
          {nav === 'personas' &&
          <PersonasView persona={persona} setPersona={setPersona}
          lang={lang} setLang={changeLang} accent={tweaks.accent} />
          }
          {nav === 'providers' &&
          <ProvidersView provider={provider} setProvider={changeProvider}
          accent={tweaks.accent} />
          }
          {nav === 'settings' &&
          <SettingsView accent={tweaks.accent} tools={tools} setTools={setTools}
          muted={muted} setMuted={setMuted} lang={lang} setLang={changeLang} />
          }
        </main>
      </div>
    </LangRoot>);

}

// ── Mobile App ──────────────────────────────────────────────────────────────

function MobileApp({ tweaks }) {
  const [nav, setNav] = useState('call');
  const [callState, setCallState] = useState('speaking');
  const routing = useSessionRouting({ callState, setCallState });
  const [tools, setTools] = useState(TOOLS_DEFAULT);
  const [muted, setMuted] = useState(false);
  const [mobileMic, setMobileMic] = useState('iPhone Mic');

  // First-load mock animation: speaking → listening cycle
  useEffect(() => {
    if (callState !== 'speaking') return;
    const timer = setTimeout(() => setCallState('listening'), 4200);
    return () => clearTimeout(timer);
  }, [callState === 'speaking']);

  const { lang, provider, persona, setPersona, changeLang, changeProvider, notice } = routing;

  return (
    <LangRoot lang={lang} className={`pp-app pp-mobile ${tweaks.dark ? 'pp-dark' : ''}`} accent={tweaks.accent}>
      <TopBar compact callState={callState} />
      <MobileStatus persona={persona} provider={provider} callState={callState} />
      <RoutingNotice notice={notice} />

      {nav === 'call' &&
      <MobileCall tweaks={tweaks} callState={callState} setCallState={setCallState}
      persona={persona} provider={provider} lang={lang} setLang={changeLang}
      tools={tools} muted={muted} setMuted={setMuted} />
      }
      {nav === 'personas' &&
      <MobilePersonas persona={persona} setPersona={setPersona} lang={lang}
      setLang={changeLang} accent={tweaks.accent} />
      }
      {nav === 'providers' &&
      <MobileProviders provider={provider} setProvider={changeProvider} accent={tweaks.accent} />
      }
      {nav === 'settings' &&
      <MobileSettings accent={tweaks.accent} tools={tools} setTools={setTools}
      muted={muted} setMuted={setMuted} mic={mobileMic} setMic={setMobileMic}
      lang={lang} setLang={changeLang} />
      }

      <MobileTabs nav={nav} setNav={setNav} />
    </LangRoot>);

}

// iOS-ish status row under the compact top bar.
function MobileStatus({ persona, provider, callState }) {
  const t = useT();
  const live = !(callState === 'idle' || callState === 'ended');
  return (
    <div className="pp-mobile-status">
      <span>{persona.name} · {provider.name}</span>
      <span>● {t(live ? 'status.live' : callState === 'ended' ? 'status.ended' : 'status.idle')}</span>
    </div>);
}

function MobileCall({ tweaks, callState, setCallState, persona, provider, lang, setLang, tools, muted, setMuted }) {
  const t = useT();
  const [sheetOpen, setSheetOpen] = useState(false);
  const [toolsOpen, setToolsOpen] = useState(false);
  const [transcriptIdx] = useState(TRANSCRIPT_SCRIPT.length - 1);
  const caption = captionFor(t, callState, true);

  // Only the cascade STT engine has a manual end-of-turn (half-duplex). Mirrors
  // the codebase's session.canSendTurn (engine === 'cascade').
  const canSendTurn = provider.engine === 'cascade';
  // Mirrors the codebase's session.sendTurnEnabled: the design mock simply
  // tracks LISTENING, while the app keeps SEND armed through dead-air capture
  // (VAD closed, reply not yet committed) so late speech still lands.
  const sendTurnEnabled = canSendTurn && callState === 'listening';
  const idle = callState === 'idle' || callState === 'ended';

  const handleCall = () => {
    if (idle) {
      setCallState('connecting');
      setTimeout(() => setCallState('listening'), 1200);
      setTimeout(() => setCallState('speaking'), 3000);
    } else {
      setCallState('ended');
    }
  };

  const handleInterrupt = () => {
    if (callState === 'speaking') {
      setCallState('interrupted');
      setTimeout(() => setCallState('listening'), 800);
    }
  };

  // Commit the user's turn (cascade STT): close listening, let the agent reply.
  const handleSendTurn = () => {
    if (sendTurnEnabled) setCallState('speaking');
  };

  const visible = TRANSCRIPT_SCRIPT.slice(0, transcriptIdx + 1);

  return (
    <>
      <div className="pp-mobile-stage">
        <div className="pp-mobile-stage-top">
          <LangSwitch compact lang={lang} onChange={setLang} />
          {tweaks.providerPreview && <Tag mono>{t('call.via')} {provider.name}</Tag>}
        </div>

        {/* 50/50 split — orb area on top, caption area on bottom */}
        <div className="pp-mobile-body">
          <div className="pp-orb-area pp-mobile-orb-area">
            <div className="pp-orb-fit pp-mobile-orb-fit">
              <Orb state={callState} style={tweaks.orbStyle} size="100%" accent={tweaks.accent} dark={tweaks.dark} manual={canSendTurn} />
            </div>
            {(callState === 'listening' || callState === 'interrupted') && <Soundbars count={8} />}
            <div className="pp-mobile-state">
              <span className={`pp-call-state-dot pp-state-${callState}`} />
              {t(`call.state.${callState}`)}
            </div>
            {sendTurnEnabled &&
            <div className="pp-call-manual-hint">{t('call.manualHintShort')}</div>
            }
          </div>

          {tweaks.transcript !== 'off' &&
          <div className="pp-caption-area pp-mobile-caption-area">
              <ScrollArea className="pp-caption-scroll" dark={tweaks.dark}>
                <div className="pp-mobile-caption" key={caption}>
                  <span style={{ color: 'var(--accent)' }}>“</span>{caption}<span style={{ color: 'var(--accent)' }}>”</span>
                </div>
              </ScrollArea>
            </div>
          }
        </div>
      </div>

      {/* Transcript bottom sheet */}
      {tweaks.transcript === 'drawer' &&
      <div className={`pp-mobile-sheet ${sheetOpen ? 'open' : ''}`}>
          <div className="pp-mobile-sheet-handle" onClick={() => setSheetOpen((o) => !o)}>
            {sheetOpen ? t('transcript.hide') : t('transcript.show', { n: visible.length })}
          </div>
          <ScrollArea className="pp-mobile-sheet-scroll" dark={tweaks.dark}>
            <div className="pp-mobile-sheet-body">
              {visible.map((turn, i) =>
            <TranscriptTurn key={i} who={turn.who} text={turn.text} persona={persona} at={`00:${String(i * 7).padStart(2, '0')}`} />
            )}
            </div>
          </ScrollArea>
        </div>
      }

      <div className="pp-mobile-controls">
        <Btn small onClick={() => setMuted((m) => !m)} active={muted}
        aria-label={t(muted ? 'aria.unmute' : 'aria.mute')}><MicGlyph muted={muted} /></Btn>
        <Btn small onClick={handleInterrupt} disabled={callState !== 'speaking'}
        aria-label={t('aria.interrupt')}><InterruptGlyph /></Btn>
        {canSendTurn &&
        <Btn small primed={sendTurnEnabled} onClick={handleSendTurn} disabled={!sendTurnEnabled}
        aria-label={t('aria.send')}><SendGlyph /></Btn>
        }
        <Btn primary onClick={handleCall} danger={!idle}
        aria-label={t(idle ? 'aria.call' : 'aria.hangup')}>
          {idle ? <WaveGlyph /> : <PhoneHangGlyph />}
        </Btn>
        <ToolsButton tools={tools} open={toolsOpen} setOpen={setToolsOpen} />
      </div>
    </>);
}

// Compact page header for the mobile screens.
function MobilePageHd({ eyebrow, title, children }) {
