}

function MobileProviders({ provider, setProvider, accent }) {
  const t = useT();
  return (
    <div style={{ flex: '1 1 auto', overflow: 'auto' }}>
      <MobilePageHd eyebrow={t('providers.eyebrow')} title={t('providers.titleShort')} />
      <table className="pp-table">
