}

function MobileSettings({ accent, tools, setTools, muted, setMuted, mic, setMic, lang, setLang }) {
  const t = useT();
  return (
    <div style={{ flex: '1 1 auto', overflow: 'auto' }}>
      <MobilePageHd eyebrow={t('settings.eyebrowShort')} title={t('settings.title')} />
      <div className="pp-settings-sec">
